TWComponent.script:
tw.local.tempSequence = ""+tw.local.sequence[0].Request_Number;
tw.local.BPM_Request_Number = "";
tw.local.date = new tw.object.Date();
tw.local.year = tw.local.date.getFullYear()+"";

tw.local.BPM_Request_Number += tw.local.branchCode+"04"+tw.local.year.substring(2,4);
for (var i=0; i<(7-tw.local.tempSequence.length); i++) {
	tw.local.BPM_Request_Number += "0";
}
tw.local.BPM_Request_Number += tw.local.tempSequence;

